def strategy(history, rng):
    n = len(history)
    if n < 10:
        return 'C'
    if n == 99:
        return 'D'

    opp = [h[1] for h in history]
    me = [h[0] for h in history]
    opp_d = sum(1 for a in opp if a == 'D')
    my_d = sum(1 for a in me if a == 'D')
    last_opp = opp[-1]
    last_me = me[-1]

    # If opponent never defected, mostly cooperate but occasionally probe after 15 rounds.
    if opp_d == 0:
        if n >= 15:
            if rng.random() < 0.1:
                return 'D'
        return 'C'

    # If opponent is almost always defecting, just defect.
    if opp_d / n > 0.8:
        return 'D'

    # Detect if opponent has defected in at least 4 of the last 5 rounds.
    if n >= 5:
        recent = opp[-5:]
        if sum(1 for a in recent if a == 'D') >= 4:
            return 'D'

    # Score gap adjustment for later rounds.
    if n >= 40:
        if opp_d > my_d + 2:
            return 'D'
        if my_d > opp_d + 4:
            return 'C'

    # If mutual cooperation is very high, occasionally test/exploit.
    if n >= 20:
        cc = sum(1 for a, b in history if a == 'C' and b == 'C')
        if cc / n > 0.8 and opp_d > 0:
            if rng.random() < 0.15:
                return 'D'

    # If opponent defected last round, handle retaliation/forgiveness.
    if last_opp == 'D':
        if last_me == 'C':
            # If they defected twice in a row, punish; otherwise forgive single defection.
            if n >= 2 and opp[-2] == 'D':
                return 'D'
            return 'C'
        else:
            # Both defected. Try to break long DD loops.
            dd_streak = 0
            for i in range(n - 1, -1, -1):
                if opp[i] == 'D' and me[i] == 'D':
                    dd_streak += 1
                else:
                    break
            if dd_streak >= 3:
                return 'C'
            return 'D'

    # If opponent cooperated last round.
    if last_opp == 'C':
        if last_me == 'D':
            return 'C'
        return 'C'

    return 'C'
